		}
		errSq += diff * diff
		sq += float64(want[i]) * float64(want[i])
	}
	d.RMS = math.Sqrt(sq / float64(len(want)))
	d.ErrRMS = math.Sqrt(errSq / float64(len(want)))
	return d
}

