func load(name string) []float32 {
	raw, err := os.ReadFile("reference/out/kokoro/" + name + ".bin")
	if err != nil {
		panic(err)
	}
	v := make([]float32, len(raw)/4)
	for i := range v {
		v[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
	}
	return v
}

func dev(got, want []float32) (float64, float64) {
	var worst, sq float64
	for i := range got {
		d := math.Abs(float64(got[i]) - float64(want[i]))
		if d > worst {
			worst = d
		}
		sq += float64(want[i]) * float64(want[i])
	}
	return worst, math.Sqrt(sq / float64(len(want)))
}

func main() {
	const nfft, hop, bins, frames = 20, 5, 11, 15601
	src := load("har_source")
	fmt.Println("har_source", len(src))

	st, _ := audio.NewSTFT(nfft, hop, audio.HannWindow(nfft, true), true)
	st.Pad = audio.PadReflect
	fmt.Println("frames", st.Frames(len(src)))
	mag, ph := st.MagnitudePhase(src)

	// reference is [bins, frames]; transpose ours
	for _, c := range []struct {
		name string
		got  []float64
	}{{"har_spec", mag}, {"har_phase", ph}} {
		want := load(c.name)
		flat := make([]float32, len(c.got))
		for t := 0; t < frames; t++ {
			for b := 0; b < bins; b++ {
				flat[b*frames+t] = float32(c.got[t*bins+b])
			}
		}
		w, rms := dev(flat, want)
		fmt.Printf("%-10s max abs %.3g  rms %.3g  rel %.3g\n", c.name, w, rms, w/rms)
	}

	spec, phase := load("gen_spec"), load("gen_phase")
	m64 := make([]float64, frames*bins)
	p64 := make([]float64, frames*bins)
	for t := 0; t < frames; t++ {
		for b := 0; b < bins; b++ {
			m64[t*bins+b] = float64(spec[b*frames+t])
			p64[t*bins+b] = float64(phase[b*frames+t])
		}
	}
	is, _ := audio.NewISTFT(nfft, hop, audio.HannWindow(nfft, true), true)
	fmt.Println("istft samples", is.Samples(frames))
	out, err := is.Apply(m64, p64, frames)
	if err != nil {
		panic(err)
	}
