		+"%.0fx below the rms", undefined, har.Rows*bins, loudest, rms/loudest)
	if worstMag > 1e-5 {
		t.Errorf("the excitation's magnitude spectrum should be exact, max abs %.3g", worstMag)
	}
	// The claim is that every disagreement is a phase of nothing. Bounding
	// the loudest one against the spectrum's own rms is what makes that a
	// measurement rather than an assertion.
	if loudest > rms/1e4 {
		t.Errorf("a phase disagrees at magnitude %.3g, only %.0fx below the rms %.3g",
			loudest, rms/loudest, rms)
	}
}

