#version 450

#extension GL_KHR_shader_subgroup_basic : enable

// Per-channel sum and sum of squares over a chunk of frames, for the AdaIN
// that precedes every convolution in kokoro's vocoder (SPEECH.md T4).
//
// AdaIN normalises each *channel* over time — an instance norm, not a layer
// norm — so the reduction runs down a column of a channel-last [T, C]
// activation, which is the awkward direction. It is done anyway: holding the
// tensor channel-last is what makes the convolutions GEMMs (S7), and a
// reduction is one pass while a transpose would be two.
//
// The access is still coalesced, because the workgroup is laid out across
// *channels* rather than along the column: 256 threads cover 256/C row groups
// of C consecutive channels, so one wave's addresses are one contiguous run
// of a row. The column direction is the loop, not the lane index.
//
// One workgroup per chunk of frames; the partials are reduced by
// kokoro_affine.comp, which is what makes this parallel over a 15601-frame
// tensor instead of one workgroup per channel.
//
//   pc.inOff   [T, C] fp32 activations
//   pc.outOff  [chunks, 2C] fp32 partials: sums then sums of squares
//   pc.tokens  T
//   pc.dim     C, a power of two
//   pc.aux0    frames per chunk
//   pc.aux2    log2(C)

#include "dit_common.glsl"

#define NTHREADS 256
layout(local_size_x = NTHREADS) in;

shared float ssum[NTHREADS];
shared float ssq[NTHREADS];

void main() {
    uint C = pc.dim;
    uint tid = gl_LocalInvocationID.x;
    uint c = tid & (C - 1u);
    uint rg = tid >> pc.aux2;
    uint groups = uint(NTHREADS) >> pc.aux2;

    uint t0 = gl_WorkGroupID.x * pc.aux0;
    uint t1 = min(t0 + pc.aux0, pc.tokens);

    float s = 0.0, q = 0.0;
    for (uint t = t0 + rg; t < t1; t += groups) {
        float v = act[pc.inOff + t * C + c];
        s += v;
        q += v * v;
    }
    ssum[tid] = s;
    ssq[tid] = q;
    barrier();
    if (rg == 0u) {
        for (uint g = 1u; g < groups; g++) {
            s += ssum[(g << pc.aux2) + c];
            q += ssq[(g << pc.aux2) + c];
        }
        act[pc.outOff + gl_WorkGroupID.x * 2u * C + c] = s;
        act[pc.outOff + gl_WorkGroupID.x * 2u * C + C + c] = q;
    }
}
GLSL
cat > kokoro_affine.comp <<'GLSL'
#version 450

// Reduce kokoro_stats.comp's partials into the per-channel affine an AdaIN
// applies, folding the style vector's gamma and beta into it.
//
// The whole of AdaIN is then two numbers per channel — a scale and a shift —
// and applying it is one fused elementwise pass (kokoro_act.comp). The style
// affine costs nothing per frame because it *is* per channel: `fc` is a
// [2C, 128] projection of one vector for the whole utterance, so the host
// computes gamma and beta once at upload and this pass never sees the style.
//
//   pc.inOff   [chunks, 2C] partials
//   pc.outOff  [2C] scale then shift
//   pc.wOff    [2C] gamma then beta, precomputed per utterance
//   pc.tokens  T, the divisor
//   pc.dim     C
//   pc.aux0    chunks
//   pc.eps     float bits

#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint C = pc.dim;
    float n = float(pc.tokens);
    for (uint c = gl_LocalInvocationID.x; c < C; c += 256u) {
        float s = 0.0, q = 0.0;
        for (uint k = 0u; k < pc.aux0; k++) {
            s += act[pc.inOff + k * 2u * C + c];
            q += act[pc.inOff + k * 2u * C + C + c];
        }
        float mean = s / n;
        // E[x^2] - E[x]^2 rather than a second centred pass. The activations
        // here are post-convolution and mean-free to within their own scale,
        // so the cancellation is mild; TestGPUAdaIN bounds it against the
        // two-pass CPU reference rather than assuming it.
        float variance = max(q / n - mean * mean, 0.0);
        float inv = inversesqrt(variance + uintBitsToFloat(pc.eps));
        float scale = (1.0 + wbuf[pc.wOff + c]) * inv;
        act[pc.outOff + c] = scale;
        act[pc.outOff + C + c] = wbuf[pc.wOff + C + c] - mean * scale;
    }
}
GLSL
cat > kokoro_act.comp <<'GLSL'
#version 450

#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable

// Apply an AdaIN affine, optionally a Snake, and narrow into the fp16 arena
// the convolution's A operand is read from — one pass over the tensor for
// what the reference does in three.
//
// The destination is a *bordered* arena: pc.lda-wide rows with `border` zero
// rows before and after the signal, so the convolution's zero padding is in
// the data and its taps are branchless (dit_gemm.comp's A_CONV). This pass
// only ever writes rows [0, T), so the border it was allocated with survives.
//
// SNAKE adds the generator's activation, x + sin(ax)^2/a with a learned `a`
// per channel. It is fused here rather than being a pass of its own because
// the alternative is a second full round trip of a [15601, 128] tensor for
// two instructions of arithmetic.
//
//   pc.inOff   [T, C] fp32 input
//   pc.outOff  fp16 destination, row stride pc.lda
//   pc.wOff    [C] alpha, when SNAKE
//   pc.aux0    [2C] scale then shift, in the fp32 arena
//   pc.aux2    log2(C)

#include "dit_common.glsl"

layout(binding = 2) buffer HAct { float16_t hact[]; };

#ifndef SNAKE
#define SNAKE 0
#endif

