// Run executes one block over the uploaded input, leaving the result in the
// running value.
func (g *GPUBlocks) Run(block int) error {
	d, _, err := g.graph(block)
	if err != nil {
		return err
	}
	d = append([]vk.MultiDispatch{g.elementwise("copy", g.aIn, g.aX, noW)}, d...)
	return submit(d)
